// ArticleExtensionDeclaration registers the extension owner and slots of Article, plus a deletion observer
// that removes its extension data when a model is hard-deleted through any connection. Register it with application Builder.Models.
func ArticleExtensionDeclaration() slots.Declaration {
	s := ArticleExtensions()
	parts := slots.Parts{
		Translations: []translations.Registration{s.Title.Registration()},
		Attachments:  []attachments.Registration{s.Cover.Registration(), s.Gallery.Registration()},
		Metadata:     []metadata.Registration{s.SEO.Registration()},
		Slots:        []extensions.SlotDescription{s.Title.Describe(), s.Cover.Describe(), s.Gallery.Describe(), s.SEO.Describe()},
	}
	return slots.Declare(ArticleExtensionOwner().Registration(), parts, func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve slots.ResolveRuntime) error {
		name, err := slots.ObserverName[Article]()
		if err != nil {
			return err
		}
		return RegisterArticleObserver(registrar, pool, lifecycle.NewDeletionObserver[Article, ArticleHooks](name), func(resolver foundation.Resolver) (func() ArticleHooks, error) {
			runtime, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			cleanup, err := slots.NewCleanup(runtime, ArticleExtensionOwner(), parts, Article.FoundryReference)
			if err != nil {
				return nil, err
			}
			hooks := ArticleHooks{Deleted: func(ctx context.Context, tx *database.Tx, changes ArticleChanges) error {
				return cleanup.Deleted(ctx, tx, changes.Before(), changes.Operation())
			}}
			return func() ArticleHooks { return hooks }, nil
		})
	})
}

